CREATE FUNCTION gridex_ediel_ack_guide.require_prodat_unused_document_v1(p_raw text)
RETURNS void LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $$
DECLARE cfg jsonb;tokens jsonb;bgm jsonb;position integer;
BEGIN
 SELECT projection#>'{constraints,PRODAT}' INTO STRICT cfg
 FROM gridex_ediel_ack_guide.editions
 WHERE source_version='a30473a34535076e12e46386563adb3fa36431a0e7a245fc1be666c5737e8708';
 tokens:=gridex_utilts_binding.wire_tokens_v1(p_raw);
 -- The existing syntax/source owner rejects unreadable or wrong profiles.
 -- This projection adds no alternate family inference or body parser.
 IF tokens IS NULL OR NOT EXISTS(SELECT FROM jsonb_array_elements(tokens)t
  WHERE t->>'tag'='UNH' AND t#>'{elements,2}'=cfg->'technicalProfile') THEN RETURN;END IF;
 FOR bgm IN SELECT t FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='BGM' LOOP
  FOR position IN SELECT value::integer FROM jsonb_array_elements_text(cfg->'unusedDocumentElements') LOOP
   IF EXISTS(SELECT FROM jsonb_array_elements_text(bgm->'elements'->position)component WHERE component<>'') THEN
    RAISE EXCEPTION 'ediel_prodat_aperak_unused_document_element';
   END IF;
  END LOOP;
 END LOOP;
END$$;

ALTER FUNCTION gridex_ediel_outbound_owner.prepare_v1(jsonb) RENAME TO prepare_before_prodat_unused_document_v1;
CREATE FUNCTION gridex_ediel_outbound_owner.prepare_v1(p_input jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN
 PERFORM gridex_ediel_ack_guide.require_prodat_unused_document_v1(p_input->>'rawPayload');
 RETURN gridex_ediel_outbound_owner.prepare_before_prodat_unused_document_v1(p_input);
END$$;

CREATE FUNCTION gridex_ediel_ack_guide.prodat_unused_document_before_storage_v1() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN
 IF NEW.direction='outbound' AND NEW.raw_payload IS NOT NULL THEN
  IF TG_OP='INSERT' THEN
   PERFORM gridex_ediel_ack_guide.require_prodat_unused_document_v1(NEW.raw_payload);
  ELSIF OLD.raw_payload IS NULL THEN
   PERFORM gridex_ediel_ack_guide.require_prodat_unused_document_v1(NEW.raw_payload);
  END IF;
 END IF;RETURN NEW;
END$$;
CREATE TRIGGER ediel_02_require_prodat_unused_document BEFORE INSERT OR UPDATE OF raw_payload ON public.ediel_messages
 FOR EACH ROW EXECUTE FUNCTION gridex_ediel_ack_guide.prodat_unused_document_before_storage_v1();

ALTER FUNCTION gridex_ack_authority.apply_v1(uuid,text,uuid,uuid,uuid) RENAME TO apply_before_prodat_unused_document_v1;
CREATE FUNCTION gridex_ack_authority.apply_v1(p_company uuid,p_environment text,p_ack uuid,p_original uuid,p_actor uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE prior jsonb;m public.ediel_messages%rowtype;
BEGIN
 -- Unchanged actual committed reader verifies current actor, own source/hash
 -- and frozen outcomes before contemporary validation. The delegate retains
 -- its exact source argument and immutable-replay checks.
 prior:=gridex_ack_authority.read_committed_v1(p_company,p_environment,p_ack,p_actor);
 IF prior IS NOT NULL THEN RETURN gridex_ack_authority.apply_before_prodat_unused_document_v1(p_company,p_environment,p_ack,p_original,p_actor);END IF;
 -- Preserve the existing apply source->ACK lock order and candidate mutex.
 LOCK TABLE public.ediel_messages IN SHARE ROW EXCLUSIVE MODE;
 -- A concurrent first application may have committed while obtaining the
 -- existing mutex. Re-read the immutable owner before any fresh guard.
 prior:=gridex_ack_authority.read_committed_v1(p_company,p_environment,p_ack,p_actor);
 IF prior IS NOT NULL THEN RETURN gridex_ack_authority.apply_before_prodat_unused_document_v1(p_company,p_environment,p_ack,p_original,p_actor);END IF;
 PERFORM id FROM public.ediel_messages WHERE id=p_original AND company_id=p_company AND environment=p_environment AND direction='outbound' FOR UPDATE;
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_ack AND company_id=p_company AND environment=p_environment AND direction='inbound' FOR UPDATE;
 IF m.id IS NOT NULL THEN PERFORM gridex_ediel_ack_guide.require_prodat_unused_document_v1(m.raw_payload);END IF;
 RETURN gridex_ack_authority.apply_before_prodat_unused_document_v1(p_company,p_environment,p_ack,p_original,p_actor);
END$$;
REVOKE ALL ON FUNCTION gridex_ediel_ack_guide.require_prodat_unused_document_v1(text),gridex_ediel_ack_guide.prodat_unused_document_before_storage_v1(),
 gridex_ediel_outbound_owner.prepare_before_prodat_unused_document_v1(jsonb),gridex_ediel_outbound_owner.prepare_v1(jsonb),
 gridex_ack_authority.apply_before_prodat_unused_document_v1(uuid,text,uuid,uuid,uuid),gridex_ack_authority.apply_v1(uuid,text,uuid,uuid,uuid)
 FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION gridex_ediel_outbound_owner.prepare_v1(jsonb),gridex_ack_authority.apply_v1(uuid,text,uuid,uuid,uuid) TO service_role;
COMMIT;
